        <div className="tools"><div className="search-box"><input className="search" type="search" aria-label="Search the menu" placeholder="Search the menu" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button type="button" className="search-clear" aria-label="Clear search" onClick={()=>setQuery('')}>×</button>}</div>{!waiter&&<button className={`btn small ${availabilityMode?'primary':''}`} onClick={()=>setAvailabilityMode(!availabilityMode)}>{availabilityMode?'Done':'Mark sold out'}</button>}</div>
